def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()

def preserve(root):
    dst=root/OUT/"PREPATCH_BLOCKED_EVIDENCE"
    dst.mkdir(parents=True,exist_ok=True)
    for rel in [
      "outputs/v0_6D1_R4_55/R4_55_RUNTIME_IDENTITY_EVIDENCE.json",
      "outputs/v0_6D1_R4_55/R4_55_EXECUTION_MANIFEST.json",
      "outputs/v0_6D1_R4_55/R4_55_PREEXECUTION_AUDIT.json",
    ]:
      p=root/rel
      if p.exists():
        q=dst/p.name
        if not q.exists(): shutil.copy2(p,q)

def main():
    root=Path.cwd();preserve(root)
    p=root/TARGET
    if not p.exists(): raise RuntimeError("R455_R1_TARGET_SOURCE_MISSING")
    cur=sha(p)
    if cur==PRE_SHA:
        srcdst=root/OUT/"PREPATCH_SOURCE";srcdst.mkdir(parents=True,exist_ok=True)
        q=srcdst/TARGET.name
        if not q.exists(): shutil.copy2(p,q)
        p.write_text(POST_TEXT,encoding="utf-8",newline="\n")
    elif cur==POST_SHA:
        pass
    else:
        raise RuntimeError(f"R455_R1_SOURCE_HASH_NOT_AUTHORIZED {cur} expected pre={PRE_SHA} or post={POST_SHA}")
    if sha(p)!=POST_SHA: raise RuntimeError("R455_R1_POSTPATCH_HASH_MISMATCH")

    mp=root/MANIFEST
    m=json.loads(mp.read_text(encoding="utf-8"))
    seen=False
    for rec in m["files"]:
        if rec["path"]==TARGET.as_posix():
            rec["sha256"]=POST_SHA;rec["bytes"]=p.stat().st_size;seen=True
    if not seen: raise RuntimeError("R455_R1_MANIFEST_TARGET_NOT_FOUND")
    mp.write_text(json.dumps(m,indent=2)+"\n",encoding="utf-8",newline="\n")

    result={
      "stage":STAGE,
      "status":"PASS_R455_R1_SEED_LEDGER_ORDER_AND_R43_CONFIG_INDEX_REPAIR_APPLIED",
      "prepatch_module_sha256":PRE_SHA,
      "postpatch_module_sha256":POST_SHA,
      "root_causes":[
        "R455_PREFLIGHT_TREATED_R452_SEED_LIST_ORDER_AS_SCIENTIFIC_AUTHORITY",
        "R455_R43_CONFIG_PARSER_ASSUMED_SEED_1_THROUGH_SEED_4_INSTEAD_OF_EXACT_FOUR_SEED_INDEX_KEYS"
      ],
      "repair":{
        "job_seed_authority":"EXACT_FOUR_UNIQUE_SEED_MEMBERSHIP_PER_JOB",
        "seed_order_authority":False,
        "r43_config_seed_parser":"EXACTLY_FOUR_DISTINCT_SEED_INDEX_KEYS_SORTED_BY_NUMERIC_INDEX",
        "raw_evidence_seed_validation":"EXACT_MEMBERSHIP_NOT_LIST_ORDER"
      },
      "governance":{
        "blocked_r455_preexecution_evidence_preserved":True,
        "scientific_engine_execution_in_blocked_r455":False,
        "r452_seed_values_modified":False,
        "r452_job_scope_modified":False,
        "r453_metric_authority_modified":False,
        "adapter_source_modified":False,
        "job_contract_modified":False,
        "numeric_thresholds_added":False,
        "canonical_state_changed":False,
        "gate_weakening_performed":False
      }
    }
    (root/OUT).mkdir(parents=True,exist_ok=True)
    (root/OUT/"R4_55_R1_REPAIR_APPLICATION.json").write_text(json.dumps(result,indent=2)+"\n",encoding="utf-8")
    print(json.dumps(result,indent=2))
    return 0
